mapper.select:
SELECT r.id, r.rule_name, r.warehouse_id, r.task_type, r.dock_type, r.wms_ready_required, r.appointment_required, r.allow_manual_insert, r.auto_call_enabled, r.require_dispatch_confirm, r.max_call_count, r.call_timeout_minutes, r.enabled, r.sort_order, r.remark, r.create_time FROM yms_call_rule r WHERE r.deleted = 0
AND r.warehouse_id = #{bo.warehouseId}
AND r.task_type = #{bo.taskType}
AND (r.dock_type = #{bo.dockType} OR r.dock_type IS NULL)
AND r.enabled = #{bo.enabled}
AND r.rule_name LIKE CONCAT('%', #{bo.ruleName}, '%')
ORDER BY r.sort_order ASC, r.create_time DESC
